export const names = Object.keys(FROSTED);
export const FROSTED_BY_CATEGORY = {"hair":"hair","hair/haircut":"haircut","hair/hair-styling":"hair-styling","hair/hair-color":"hair-color","hair/braids":"braids","hair/braids/box-braids":"box-braids","hair/braids/knotless-braids":"knotless-braids","hair/braids/cornrows":"cornrows","hair/locs":"locs","hair/hair-extensions":"hair-extensions","hair/hair-treatments":"hair-treatments","beard-shave":"beard-shave","brows-lashes":"brows-lashes","nails":"nails","nails/manicure":"manicure","nails/pedicure":"pedicure","nails/acrylic-nails":"acrylic-nails","nails/gel-nails":"gel-nails","skin-face":"skin-face","skin-face/facials":"facials","skin-face/face-waxing":"waxing","body":"body","body/massage":"massage","body/body-waxing":"body-waxing","body/spray-tan":"spray-tan","makeup":"makeup","permanent-makeup":"permanent-makeup","tattoo-piercing":"tattoo-piercing","kids":"kids","house-call":"house-call"};
/** Frosted icon name for a category path, nearest mapped ancestor wins; null when nothing matches. */
export const frostedForCategory = (path) => { const parts = String(path || '').split('/'); while (parts.length) { const hit = FROSTED_BY_CATEGORY[parts.join('/')]; if (hit) return hit; parts.pop(); } return null; };
/** Standalone <svg> markup; pass size in px. */
export const svg = (name, size = 64) => { const f = FROSTED[name]; if (!f) throw new Error('Unknown MBX frosted icon: ' + name); return f.svg.replace(/width="\d+" height="\d+"/, 'width="' + size + '" height="' + size + '"'); };
/** Path under the package for a PNG rendition: png(name, 2) → "png/<name>@2x.png" (128·scale px). */
export const png = (name, scale = 2) => 'png/' + name + '@' + scale + 'x.png';
